#include <streambuf>
#include <ios>
#include <locale>
#include <string>
#include <cassert>
#include <type_traits>
#include <utility>
struct Buffer : std::streambuf {
    char input[4] = "abc", output[8]{};
    Buffer() {
        setg(input, input, input + 3);
        setp(output, output + 8);
    }
    void exercise() {
        assert(gptr() == input);
        gbump(1);
        assert(*gptr() == 'b');
        gbump(-1);
        assert(pptr() == output);
        assert(showmanyc() == 0);
        assert(uflow() == 'a');
        gbump(-1);
        (void)pbackfail();
    }
    int_type underflow() override {
        return gptr() < egptr() ? traits_type::to_int_type(*gptr())
                                : traits_type::eof();
    }
    void assign(const Buffer &other) { std::streambuf::operator=(other); }
    void exchange(Buffer &other) { swap(other); }
    pos_type seekoff(off_type offset, std::ios::seekdir, std::ios::openmode) override {
        setg(input, input + offset, input + 3);
        return offset;
    }
    pos_type seekpos(pos_type position, std::ios::openmode mode) override {
        return seekoff(off_type(position), std::ios::beg, mode);
    }
};
int main() {
    Buffer buffer, copy;
    buffer.exercise();
    copy.assign(buffer);
    copy.exchange(buffer);
    assert(buffer.sgetc() == 'a');
    assert(buffer.sbumpc() == 'a');
    assert(buffer.snextc() == 'c');
    assert(buffer.in_avail() >= 1);
    char read[2]{};
    buffer.pubseekpos(0, std::ios::in);
    assert(buffer.sgetn(read, 2) == 2);
    assert(read[0] == 'a');
    buffer.pubseekoff(0, std::ios::beg, std::ios::in);
    buffer.pubimbue(std::locale::classic());
    assert(buffer.getloc() == std::locale::classic());
    assert(buffer.pubsync() == 0);
}
